"""STEP 2/3 – Multi-pass blocking and candidate generation.

Blocking reduces the number of records that need detailed comparison.
Instead of comparing one incoming record against 10,000 master records, the
system first narrows the search to a smaller candidate set using cheap,
exact look-ups on "blocking keys".

Six passes are implemented.  A master record becomes a candidate if it shares
a key with the incoming record in ANY enabled pass.  We remember *which*
passes produced each candidate so the explanation can say
"Candidate C01023 generated by: Phone block AND City + surname block".
"""
from __future__ import annotations

from collections import Counter, defaultdict

from matching.preprocessing import normalize_record

# pass id → (human label, short description)
BLOCKING_PASSES: dict[str, tuple[str, str]] = {
    "phone": ("PASS 1 – Exact normalized phone", "Same 10-digit phone number"),
    "email": ("PASS 2 – Exact normalized email", "Same lower-cased email address"),
    "postal_surname": ("PASS 3 – Postal code + surname", "Same PIN code and same surname"),
    "city_surname": ("PASS 4 – City + surname", "Same city and same surname"),
    "phonetic_surname_city": ("PASS 5 – Phonetic surname + city", "Surname sounds alike (Soundex) in the same city"),
    "first_token_city": ("PASS 6 – First name token + city", "Same first name in the same city"),
}

# Fields for which we count value frequencies (used by rare-value weighting)
FREQUENCY_FIELDS = ["name", "email", "phone", "dob", "company", "address"]


def blocking_key(pass_id: str, normalized: dict) -> str | None:
    """Return the blocking key of a normalized record for the given pass."""
    n, d = normalized["norm"], normalized["derived"]
    if pass_id == "phone":
        return n["phone"]
    if pass_id == "email":
        return n["email"]
    if pass_id == "postal_surname":
        return f"{n['postal_code']}|{d['surname']}" if n["postal_code"] and d["surname"] else None
    if pass_id == "city_surname":
        return f"{n['city']}|{d['surname']}" if n["city"] and d["surname"] else None
    if pass_id == "phonetic_surname_city":
        return f"{n['city']}|{d['surname_soundex']}" if n["city"] and d["surname_soundex"] else None
    if pass_id == "first_token_city":
        return f"{n['city']}|{d['first_token']}" if n["city"] and d["first_token"] else None
    raise ValueError(f"Unknown blocking pass: {pass_id}")


class BlockingIndex:
    """In-memory index of the master database.

    Built once per master snapshot and reused for every incoming record.
    """

    def __init__(self, master_records: list[dict]):
        self.records: dict[str, dict] = {}            # entity_id → normalized record
        self.indexes: dict[str, dict[str, list[str]]] = {p: defaultdict(list) for p in BLOCKING_PASSES}
        self.value_counts: dict[str, Counter] = {f: Counter() for f in FREQUENCY_FIELDS}

        for rec in master_records:
            entity_id = rec["entity_id"]
            normalized = normalize_record(rec)
            self.records[entity_id] = normalized
            for pass_id in BLOCKING_PASSES:
                key = blocking_key(pass_id, normalized)
                if key:
                    self.indexes[pass_id][key].append(entity_id)
            for f in FREQUENCY_FIELDS:
                value = normalized["norm"].get(f)
                if value:
                    self.value_counts[f][value] += 1

    # ----------------------------------------------------------------- info
    @property
    def size(self) -> int:
        return len(self.records)

    def get(self, entity_id: str) -> dict | None:
        return self.records.get(entity_id)

    def frequency(self, field: str, value: str | None) -> int:
        if not value or field not in self.value_counts:
            return 0
        return self.value_counts[field].get(value, 0)

    # ----------------------------------------------------------- candidates
    def candidates(self, normalized_incoming: dict, passes: list[str], full_scan_below: int = 0) -> dict[str, list[str]]:
        """Return {entity_id: [pass_id, ...]} for all candidates.

        If the master database is smaller than `full_scan_below`, every record
        is returned (blocking has no benefit for tiny datasets); the pass list
        then contains "full_scan".
        """
        if self.size and self.size < full_scan_below:
            return {eid: ["full_scan"] for eid in self.records}

        found: dict[str, list[str]] = defaultdict(list)
        for pass_id in passes:
            if pass_id not in BLOCKING_PASSES:
                continue
            key = blocking_key(pass_id, normalized_incoming)
            if not key:
                continue
            for entity_id in self.indexes[pass_id].get(key, []):
                found[entity_id].append(pass_id)
        return dict(found)

    def block_sizes(self) -> dict[str, dict]:
        """Diagnostics for the UI: how big are the blocks in each pass."""
        out = {}
        for pass_id, idx in self.indexes.items():
            sizes = [len(v) for v in idx.values()]
            out[pass_id] = {
                "blocks": len(sizes),
                "avg_block_size": round(sum(sizes) / len(sizes), 2) if sizes else 0,
                "max_block_size": max(sizes) if sizes else 0,
            }
        return out


def pass_label(pass_id: str) -> str:
    if pass_id == "full_scan":
        return "Full scan (master database is very small)"
    return BLOCKING_PASSES.get(pass_id, (pass_id, ""))[0]


def reduction_pct(master_size: int, pool_size: int) -> float | None:
    """Candidate reduction achieved by blocking, in percent."""
    if not master_size:
        return None
    return round((1 - pool_size / master_size) * 100, 2)
